using System;using System.Net;using System.Net.Http;using System.Threading;using System.Threading.Tasks;using System.IO;using Videira;
class Fake:HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken c){return Task.FromResult(new HttpResponseMessage(HttpStatusCode.BadRequest){Content=new StringContent("{\"msg\":\"Invalid login credentials\"}")});}}
class AuthCheck{static void Main(){using(var api=new SiteApi(new Fake())){bool denied=false;try{api.Login(SiteApi.AdminEmail,"test-fixture").GetAwaiter().GetResult();}catch(Exception ex){denied=ex.Message.Contains("senha foi recusada")&&ex.Message.Contains("Recuperar acesso");}if(!denied||api.Connected)throw new Exception("Mensagem de login ou estado de sessão inválido");bool blocked=false;try{api.Recover("https://example.com/auth/v1/verify?token=x&type=recovery","test-fixture-long").GetAwaiter().GetResult();}catch(Exception ex){blocked=ex.Message.Contains("Cole o endereço");}if(!blocked)throw new Exception("Link de recuperação não validado");File.WriteAllText("work/site-app/auth-check.txt","PASS: erro de credenciais tratado, sessão permanece desconectada e link externo de recuperação rejeitado; teste sem usar conta ou senha real.");}}}
